select jsonb_build_object('checked_at',clock_timestamp(),'catalogue',(select jsonb_object_agg(name,value) from (select 'works' as name,jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by id))) as value from public.works t union all select 'authors',jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by id))) from public.authors t union all select 'editions',jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by id))) from public.editions t union all select 'descriptions',jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by work_id,language))) from public.catalog_work_descriptions t union all select 'metadata',jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by edition_id))) from public.catalog_edition_metadata t) s),'protected',(select jsonb_object_agg(name,value) from (select 'ratings' as name,jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text))) as value from public.ratings t union all select 'reading_status',jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text))) from public.user_book_status t union all select 'reading_preferences',jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text))) from public.user_reading_preferences t union all select 'accounts',jsonb_build_object('count',count(*)) from auth.users) s),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987125001 and 987125999),'editions',(select count(*) from public.editions where id between 987225001 and 987225999),'authors',(select count(*) from public.authors where id between 987325001 and 987325999))) as safety;
